      </button>
    `;
  }).join("");

  qsa(".video-float-card", world).forEach((card) => {
    const preview = qs("video", card);
    card.addEventListener("mouseenter", () => preview?.play().catch(() => {}));
    card.addEventListener("mouseleave", () => preview?.pause());
    card.addEventListener("click", () => {
