}

.room-card img,
.room-card video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.72;
  transform: scale(1.02);
  transition: transform 520ms ease, opacity 520ms ease, filter 520ms ease;
}

.room-card::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(180deg, transparent 12%, rgba(0, 0, 0, 0.82)),
    linear-gradient(90deg, rgba(255, 36, 79, 0.2), transparent 48%, rgba(77, 234, 255, 0.1));
}

.room-card span,
.room-card strong,
.room-card p {
  position: relative;
  z-index: 2;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.88);
}

.room-card span {
  color: var(--cyan);
  font-size: 0.74rem;
  font-weight: 1000;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.room-card strong {
  display: block;
  margin-top: 0.5rem;
  color: var(--ink);
  font-family: "Arial Black", Impact, sans-serif;
  font-size: clamp(1.55rem, 3vw, 3.8rem);
  line-height: 0.94;
  text-transform: uppercase;
}

.room-card p {
  max-width: 32rem;
  margin: 0.75rem 0 0;
  color: var(--soft);
  line-height: 1.45;
}

.room-card:hover {
  transform: translateY(-5px);
  border-color: rgba(77, 234, 255, 0.56);
  box-shadow: var(--shadow-cyan);
}

.room-card:hover img,
.room-card:hover video {
  opacity: 0.9;
  transform: scale(1.075);
  filter: saturate(1.15) contrast(1.06);
}

.signal-strip {
  min-height: 78svh;
  display: grid;
