      if (!target) return;
      event.preventDefault();
      target.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });

  qsa("[data-open-dashboard]").forEach((node) => {
    node.addEventListener("click", () => {
      window.location.href = "dashboard.html";
    });
  });
}

