  z-index: 1;
  width: min(48vw, 48rem);
  height: min(58vh, 36rem);
  object-fit: cover;
  opacity: 0.82;
  border: 1px solid rgba(255, 246, 238, 0.18);
  box-shadow:
    0 0 54px rgba(255, 36, 79, 0.24),
    0 28px 82px rgba(0, 0, 0, 0.56);
  filter: saturate(1.08) contrast(1.05);
}

.floating-video-world {
  position: absolute;
  inset: 0;
  z-index: 2;
  transform-style: preserve-3d;
  transform: rotateX(58deg) rotateZ(var(--video-orbit-z, 0deg));
  animation: videoOrbitSpin 38s linear infinite;
}

.floating-video-world.is-held {
  animation-play-state: paused;
}

.video-float-card {
  position: absolute;
  left: 50%;
  top: 50%;
  width: clamp(9rem, 15vw, 17rem);
  min-height: clamp(12rem, 19vw, 22rem);
  display: grid;
  align-content: end;
  overflow: hidden;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--card-color) 60%, rgba(255, 255, 255, 0.2));
  border-radius: 8px;
  color: var(--ink);
  background: #050507;
  box-shadow: 0 0 30px color-mix(in srgb, var(--card-color) 42%, transparent), 0 20px 54px rgba(0, 0, 0, 0.55);
  cursor: pointer;
  transform:
    translate(-50%, -50%)
    rotateZ(calc(var(--card-angle) + var(--manual-angle, 0deg)))
    translateX(clamp(16rem, 34vw, 34rem))
    rotateZ(calc((var(--card-angle) + var(--manual-angle, 0deg)) * -1))
    rotateX(-58deg);
  transition: scale 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
}

.video-float-card.is-active,
.video-float-card:hover {
  scale: 1.08;
  border-color: rgba(255, 255, 255, 0.78);
  box-shadow: 0 0 38px color-mix(in srgb, var(--card-color) 72%, transparent), 0 28px 76px rgba(0, 0, 0, 0.68);
}

.video-float-card video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.82;
}

.video-float-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, transparent 18%, rgba(0, 0, 0, 0.88)),
    repeating-linear-gradient(0deg, transparent 0 8px, rgba(255, 255, 255, 0.055) 9px);
  pointer-events: none;
}

.video-float-card span,
.video-float-card strong,
.video-float-card small {
  position: relative;
  z-index: 1;
  display: block;
  margin: 0 0.82rem;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.92);
}

.video-float-card span {
  color: var(--cyan);
  font-size: 0.66rem;
  font-weight: 1000;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.video-float-card strong {
  margin-top: 0.35rem;
  font-family: "Arial Black", Impact, sans-serif;
  font-size: clamp(1rem, 1.8vw, 1.7rem);
  line-height: 0.96;
  text-transform: uppercase;
}

.video-float-card small {
  margin-top: 0.45rem;
  margin-bottom: 0.85rem;
  color: var(--soft);
  font-size: 0.66rem;
  font-weight: 900;
  text-transform: uppercase;
}

.hero-stage-panel {
  position: absolute;
  right: clamp(1rem, 4vw, 4rem);
  bottom: clamp(6rem, 10vw, 8rem);
  z-index: 6;
  width: min(28rem, calc(100vw - 2rem));
  padding: 1rem;
  border: 1px solid rgba(255, 246, 238, 0.18);
  border-radius: 8px;
  background: rgba(3, 3, 5, 0.76);
  backdrop-filter: blur(18px);
}

.hero-stage-panel strong {
  display: block;
  color: var(--ink);
  font-family: "Arial Black", Impact, sans-serif;
  font-size: clamp(1.4rem, 3vw, 2.6rem);
  line-height: 0.95;
  text-transform: uppercase;
}

.hero-stage-panel span {
  display: block;
  margin-top: 0.66rem;
  color: var(--soft);
  line-height: 1.45;
}

.stage-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
}

.quick-hero {
  min-height: 100svh;
}

.quick-hero::before {
  background:
    linear-gradient(90deg, rgba(3, 3, 5, 0.9) 0%, rgba(3, 3, 5, 0.34) 38%, rgba(3, 3, 5, 0.22) 62%, rgba(3, 3, 5, 0.88) 100%),
    linear-gradient(0deg, var(--bg), transparent 42%, rgba(3, 3, 5, 0.24));
}

.hero-storyscape-frame {
  position: absolute;
  inset: 0;
  z-index: -3;
  width: 100%;
  height: 100%;
  border: 0;
  background: #050506;
  opacity: 0.74;
  pointer-events: none;
  filter: saturate(1.2) contrast(1.08);
  transform: scale(1.035);
  transform-origin: center;
}

.hero-feature-video {
  position: absolute;
  top: clamp(8rem, 12vh, 10rem);
  right: clamp(1rem, 5vw, 5.4rem);
  z-index: 1;
  width: min(43vw, 42rem);
  height: min(56vh, 38rem);
  overflow: hidden;
  border: 1px solid rgba(255, 246, 238, 0.18);
  background: #030305;
  box-shadow:
    0 0 62px rgba(255, 36, 79, 0.24),
    0 28px 82px rgba(0, 0, 0, 0.6);
}

.hero-feature-video::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, transparent 22%, rgba(0, 0, 0, 0.72)),
    repeating-linear-gradient(0deg, transparent 0 8px, rgba(255, 255, 255, 0.055) 9px);
}

.hero-main-video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.9;
  filter: saturate(1.12) contrast(1.06);
}

.hero-feature-panel {
  right: 1rem;
  bottom: 1rem;
  z-index: 2;
  width: min(25rem, calc(100% - 2rem));
  padding: 0.86rem;
}

.stage-orbit-controls {
  position: absolute;
  left: clamp(1rem, 5vw, 5.4rem);
  bottom: clamp(3rem, 6vw, 5rem);
  z-index: 7;
}

@keyframes videoOrbitSpin {
  from {
    transform: rotateX(58deg) rotateZ(var(--video-orbit-z, 0deg));
  }
  to {
    transform: rotateX(58deg) rotateZ(calc(var(--video-orbit-z, 0deg) + 360deg));
  }
}

.eyebrow {
  margin: 0 0 0.7rem;
  color: var(--cyan);
  font-size: 0.76rem;
  font-weight: 1000;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: "Arial Black", Impact, ui-sans-serif, sans-serif;
  letter-spacing: 0;
  line-height: 0.92;
  text-transform: uppercase;
}

h1 {
  max-width: 11ch;
  color: #fff;
  font-size: clamp(4.8rem, 13vw, 13rem);
  text-shadow:
    0 0 18px rgba(255, 36, 79, 0.64),
    0 0 60px rgba(77, 234, 255, 0.24);
}

h2 {
  max-width: 13ch;
  font-size: clamp(2.7rem, 7vw, 7.2rem);
}

h3 {
  font-size: clamp(1.32rem, 2.7vw, 2.7rem);
}

.lede {
  max-width: 52rem;
  margin: 1rem 0 0;
  color: var(--soft);
  font-size: clamp(1.08rem, 2vw, 1.58rem);
  line-height: 1.48;
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  width: min(62rem, 100%);
  margin-top: 2rem;
  border: 1px solid var(--line);
  background: var(--line);
}

.stats div {
  min-height: 6.3rem;
  padding: 1rem;
  background: rgba(3, 3, 5, 0.72);
}

.stats strong {
  display: block;
  color: var(--gold);
  font-size: clamp(1.7rem, 4vw, 3.3rem);
  font-weight: 1000;
  line-height: 1;
}

.stats span {
  display: block;
  margin-top: 0.38rem;
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 800;
  text-transform: uppercase;
}

.command-strip {
  position: fixed;
  left: 50%;
  bottom: max(1rem, env(safe-area-inset-bottom));
  z-index: 75;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.44rem;
  width: min(94vw, 48rem);
  padding: 0.44rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 999px;
  background: rgba(3, 3, 5, 0.74);
  box-shadow: 0 18px 54px rgba(0, 0, 0, 0.5), var(--shadow-red);
  backdrop-filter: blur(18px);
  transform: translateX(-50%);
}

.command-strip button,
.command-strip .button {
  min-height: 2.4rem;
  padding: 0.54rem 0.82rem;
  font-size: 0.72rem;
  font-weight: 1000;
  text-transform: uppercase;
}

.section {
  padding: clamp(5.3rem, 10vw, 10rem) clamp(1rem, 5vw, 5.4rem);
}

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 2rem;
  margin-bottom: 2rem;
}

.section-head p {
  max-width: 38rem;
  margin: 0;
  color: var(--soft);
  font-size: 1rem;
  line-height: 1.65;
}

.split {
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.18fr);
  gap: clamp(1.4rem, 4vw, 4.8rem);
  align-items: center;
}

.copy p {
  color: var(--soft);
  line-height: 1.7;
}

.video-stage,
.player,
.video-tile,
.track-button,
.post-card,
.gallery button,
.dashboard-shell,
.edit-table,
.room-note,
.system-plate {
  border: 1px solid var(--line);
  background: var(--panel);
  backdrop-filter: blur(18px);
}

.video-stage {
  position: relative;
  min-height: clamp(24rem, 56vw, 46rem);
  overflow: hidden;
  box-shadow: var(--shadow-red);
}

.video-stage video {
  display: block;
  width: 100%;
  height: 100%;
  min-height: inherit;
  object-fit: cover;
}

.video-stage::after,
.video-tile::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, transparent 18%, rgba(0, 0, 0, 0.72)),
    repeating-linear-gradient(0deg, transparent 0 8px, rgba(255, 255, 255, 0.06) 9px);
  opacity: 0.7;
}

.video-caption {
  position: absolute;
  left: clamp(1rem, 3vw, 2rem);
  right: clamp(1rem, 3vw, 2rem);
  bottom: clamp(1rem, 3vw, 2rem);
  z-index: 2;
}

.video-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.video-tile {
  position: relative;
  min-height: 24rem;
  overflow: hidden;
}

.video-tile video,
.video-tile img {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 24rem;
  object-fit: cover;
  filter: saturate(1.1) contrast(1.06);
}

.video-tile-body {
  position: absolute;
  left: 1rem;
  right: 1rem;
  bottom: 1rem;
  z-index: 2;
}

.video-tile-body p {
  margin: 0.45rem 0 0;
  color: var(--soft);
  line-height: 1.45;
}

.music-grid {
  display: grid;
  grid-template-columns: minmax(17rem, 0.8fr) minmax(0, 1.2fr);
  gap: 1rem;
  align-items: start;
}

.player {
  position: sticky;
  top: 6rem;
  padding: 1rem;
}

.player img {
  width: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  border: 1px solid var(--line);
  filter: saturate(1.1) contrast(1.08);
}

.player audio {
  width: 100%;
  margin-top: 1rem;
  accent-color: var(--red);
}

.track-list {
  display: grid;
  gap: 0.6rem;
}

.track-button {
  width: 100%;
  min-height: 5.2rem;
  display: grid;
  grid-template-columns: 3.2rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.85rem;
  padding: 0.82rem 1rem;
  border-radius: 0;
  text-align: left;
}

.track-button span {
  color: var(--red);
  font-weight: 1000;
}

.track-button strong {
  display: block;
  overflow: hidden;
  font-size: clamp(1.05rem, 2vw, 1.55rem);
  line-height: 1.05;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.track-button small {
  color: var(--cyan);
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.track-button[aria-pressed="true"] {
  border-color: rgba(255, 36, 79, 0.68);
  background: linear-gradient(90deg, rgba(255, 36, 79, 0.18), rgba(77, 234, 255, 0.08));
  box-shadow: var(--shadow-red);
}

.gallery {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.8rem;
}

.gallery button {
  position: relative;
  min-height: 23rem;
  overflow: hidden;
  padding: 0;
  border-radius: 0;
}

.gallery img {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 23rem;
  object-fit: cover;
  transition: transform 420ms ease, filter 420ms ease;
}

.gallery button:hover img {
  transform: scale(1.045);
  filter: saturate(1.16) contrast(1.08);
}

.gallery span {
  position: absolute;
  left: 0.8rem;
  right: 0.8rem;
  bottom: 0.8rem;
  color: var(--ink);
  font-size: 0.76rem;
  font-weight: 1000;
  text-align: left;
  text-transform: uppercase;
  text-shadow: 0 2px 16px #000;
}

.system-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}

.system-plate {
  min-height: 18rem;
  padding: 1.2rem;
}

.system-plate strong {
  display: block;
  color: var(--gold);
  font-family: "Arial Black", Impact, sans-serif;
  font-size: clamp(2rem, 5vw, 4.6rem);
  line-height: 0.9;
  text-transform: uppercase;
}

.system-plate p {
  color: var(--soft);
  line-height: 1.6;
}

.post-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
}

.post-card {
  min-height: 26rem;
  display: grid;
  align-content: start;
  overflow: hidden;
}

.post-card img {
  width: 100%;
  height: 14rem;
  object-fit: cover;
}

.post-card .post-body {
  padding: 1rem;
}

.post-card p {
  color: var(--soft);
  line-height: 1.55;
}

.song-orbit-section {
  position: relative;
  min-height: 100svh;
  padding: clamp(5.8rem, 10vw, 9rem) clamp(1rem, 5vw, 5.4rem);
  overflow: hidden;
  isolation: isolate;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background:
    radial-gradient(circle at 54% 42%, rgba(255, 36, 79, 0.28), transparent 28%),
    radial-gradient(circle at 46% 54%, rgba(77, 234, 255, 0.2), transparent 34%),
    linear-gradient(125deg, #030305, #130409 48%, #030305);
}

.song-orbit-section::before,
.song-orbit-section::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.song-orbit-section::before {
  z-index: -2;
  opacity: 0.5;
  background:
    linear-gradient(90deg, rgba(255, 246, 238, 0.04) 1px, transparent 1px),
    linear-gradient(180deg, rgba(255, 246, 238, 0.035) 1px, transparent 1px);
  background-size: 74px 74px;
}

.song-orbit-section::after {
  z-index: -1;
  opacity: 0.52;
  background:
    repeating-linear-gradient(0deg, transparent 0 9px, rgba(255, 255, 255, 0.055) 10px),
    linear-gradient(90deg, rgba(3, 3, 5, 0.92), transparent 50%, rgba(3, 3, 5, 0.88));
  mix-blend-mode: screen;
}

.song-orbit-stage {
  position: relative;
  min-height: clamp(35rem, 76vw, 54rem);
  perspective: 1500px;
  transform-style: preserve-3d;
  touch-action: none;
}

.song-orbit-world {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform: rotateX(62deg) rotateZ(var(--orbit-z, 0deg));
  animation: songOrbitSpin 32s linear infinite;
  animation-play-state: running;
}

.song-orbit-world.is-held {
  animation-play-state: paused;
}

.song-orb {
  position: absolute;
  left: 50%;
  top: 50%;
  width: clamp(9.3rem, 14vw, 15.8rem);
  min-height: clamp(9.3rem, 14vw, 15.8rem);
  display: grid;
  align-content: center;
  gap: 0.45rem;
  padding: 1rem;
  border: 1px solid color-mix(in srgb, var(--orb-color) 62%, rgba(255, 255, 255, 0.18));
  border-radius: 50%;
  color: var(--ink);
  text-align: center;
  background:
    radial-gradient(circle at 30% 18%, rgba(255, 255, 255, 0.5), transparent 18%),
    radial-gradient(circle at 50% 52%, color-mix(in srgb, var(--orb-color) 34%, transparent), rgba(3, 3, 5, 0.82) 72%);
  box-shadow:
    0 0 26px color-mix(in srgb, var(--orb-color) 48%, transparent),
    inset 0 0 24px rgba(255, 255, 255, 0.1);
  cursor: pointer;
  transform:
    translate(-50%, -50%)
    rotateZ(calc(var(--orb-angle) + var(--manual-angle, 0deg)))
    translateX(clamp(13rem, 31vw, 31rem))
    rotateZ(calc((var(--orb-angle) + var(--manual-angle, 0deg)) * -1))
    rotateX(-62deg);
  transition: border-color 180ms ease, box-shadow 180ms ease, scale 180ms ease;
}

.song-media-orb {
  width: clamp(10rem, 16vw, 18rem);
  min-height: clamp(13rem, 22vw, 24rem);
  display: grid;
  align-content: end;
  overflow: hidden;
  padding: 0.8rem;
  border-radius: 8px;
  background: #050507;
  transform:
    translate(-50%, -50%)
    rotateZ(calc(var(--orb-angle) + var(--manual-angle, 0deg)))
    translateX(clamp(16rem, 34vw, 34rem))
    rotateZ(calc((var(--orb-angle) + var(--manual-angle, 0deg)) * -1))
    rotateX(-62deg);
}

.song-media-orb img {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.86;
  filter: saturate(1.16) contrast(1.06);
  transition: transform 420ms ease, opacity 420ms ease, filter 420ms ease;
}

.song-media-orb::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(180deg, transparent 18%, rgba(0, 0, 0, 0.88)),
    linear-gradient(90deg, color-mix(in srgb, var(--orb-color) 28%, transparent), transparent 58%),
    repeating-linear-gradient(0deg, transparent 0 8px, rgba(255, 255, 255, 0.055) 9px);
}

.song-media-orb:hover img,
.song-media-orb.is-active img {
  opacity: 0.96;
  transform: scale(1.075);
  filter: saturate(1.24) contrast(1.1);
}

.song-orb:hover,
.song-orb.is-active {
  scale: 1.08;
  border-color: rgba(255, 255, 255, 0.76);
  box-shadow:
    0 0 32px color-mix(in srgb, var(--orb-color) 72%, transparent),
    0 0 70px rgba(77, 234, 255, 0.16),
    inset 0 0 28px rgba(255, 255, 255, 0.16);
}

.song-orb span {
  position: relative;
  z-index: 2;
  color: var(--cyan);
  font-size: 0.72rem;
  font-weight: 1000;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.92);
}

.song-orb strong {
  position: relative;
  z-index: 2;
  display: block;
  overflow-wrap: anywhere;
  font-family: "Arial Black", Impact, sans-serif;
  font-size: clamp(1rem, 1.6vw, 1.55rem);
  line-height: 0.96;
  text-transform: uppercase;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.92);
}

.song-orb small {
  position: relative;
  z-index: 2;
  color: var(--soft);
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.92);
}

.orbit-visual-core {
  position: absolute;
  inset: 6% 0 0;
  display: grid;
  place-items: center;
  pointer-events: none;
  transform-style: preserve-3d;
}

.orbit-cutout {
  position: relative;
  z-index: 3;
  height: min(74vh, 780px);
  max-width: min(72vw, 760px);
  object-fit: contain;
  opacity: 0.86;
  filter:
    drop-shadow(0 0 28px rgba(255, 36, 79, 0.7))
    drop-shadow(0 0 76px rgba(77, 234, 255, 0.24))
    drop-shadow(0 42px 76px rgba(0, 0, 0, 0.86));
  mix-blend-mode: screen;
}

.orbit-ring {
  position: absolute;
  z-index: 1;
  border: 1px solid rgba(255, 246, 238, 0.14);
  border-radius: 50%;
  transform: rotateX(68deg);
  box-shadow: 0 0 36px rgba(77, 234, 255, 0.2);
}

.ring-one {
  width: min(74vw, 58rem);
  aspect-ratio: 1;
}

.ring-two {
  width: min(58vw, 43rem);
  aspect-ratio: 1;
  border-color: rgba(255, 36, 79, 0.22);
}

.ring-three {
  width: min(42vw, 30rem);
  aspect-ratio: 1;
  border-color: rgba(255, 211, 106, 0.2);
}

.orbit-console {
  position: relative;
  z-index: 4;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 1rem;
  align-items: end;
  padding: 1rem;
  border: 1px solid var(--line);
  background: rgba(3, 3, 5, 0.78);
