}

.hero {
  position: relative;
  min-height: 100svh;
  display: grid;
  align-items: end;
  padding: clamp(7rem, 13vw, 12rem) clamp(1rem, 5vw, 5.4rem) clamp(8.2rem, 12vw, 10rem);
  overflow: hidden;
  isolation: isolate;
}

.scene-frame {
  position: absolute;
  inset: 0;
  z-index: -3;
  width: 100%;
  height: 100%;
  border: 0;
  background: #050506;
}

.hero::before {
  content: "";
  position: absolute;
