    linear-gradient(90deg, rgba(3, 3, 5, 0.9) 0%, rgba(3, 3, 5, 0.48) 42%, rgba(3, 3, 5, 0.18) 62%, rgba(3, 3, 5, 0.78) 100%),
    linear-gradient(0deg, var(--bg), transparent 38%, rgba(3, 3, 5, 0.28));
