  box-shadow: var(--shadow-red);
}

.video-stage video {
  display: block;
  width: 100%;
  height: 100%;
  min-height: inherit;
  object-fit: cover;
}

.video-stage::after,
.video-tile::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, transparent 18%, rgba(0, 0, 0, 0.72)),
    repeating-linear-gradient(0deg, transparent 0 8px, rgba(255, 255, 255, 0.06) 9px);
  opacity: 0.7;
}

.video-caption {
  position: absolute;
