  grid-template-columns: 3.2rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.85rem;
  padding: 0.82rem 1rem;
  border-radius: 0;
  text-align: left;
}

.track-button span {
  color: var(--red);
