}

.gallery button:hover img {
  transform: scale(1.045);
  filter: saturate(1.16) contrast(1.08);
}

.gallery span {
  position: absolute;
  left: 0.8rem;
  right: 0.8rem;
  bottom: 0.8rem;
  color: var(--ink);
  font-size: 0.76rem;
  font-weight: 1000;
  text-align: left;
  text-transform: uppercase;
  text-shadow: 0 2px 16px #000;
}

.system-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}

.system-plate {
